import 'dart:async';

import 'package:event_bus/event_bus.dart';
import 'package:flutter/material.dart';

import '../../../services/event_bus/events/global/wallet_sync_status_changed_event.dart';
import '../../../services/event_bus/global_event_bus.dart';
import '../../../themes/stack_colors.dart';
import '../../../utilities/constants.dart';
import '../../../utilities/util.dart';
import '../../../wallets/wallet/wallet.dart';
import '../../../widgets/animated_widgets/rotating_arrows.dart';

/// [eventBus] should only be set during testing
class WalletRefreshButton extends StatefulWidget {
  const WalletRefreshButton({
    super.key,
    required this.wallet,
    required this.initialSyncStatus,
    this.eventBus,
    this.overrideIconColor,
  });

  final Wallet wallet;
  final WalletSyncStatus initialSyncStatus;
  final EventBus? eventBus;
  final Color? overrideIconColor;

  @override
  State<WalletRefreshButton> createState() => _RefreshButtonState();
}

class _RefreshButtonState extends State<WalletRefreshButton> {
  late final EventBus eventBus;

  bool _refreshing = false;
  late RotatingArrowsController _spinController;

  late StreamSubscription<dynamic> _syncStatusSubscription;

  @override
  void initState() {
    _spinController = RotatingArrowsController();

    eventBus =
        widget.eventBus != null ? widget.eventBus! : GlobalEventBus.instance;

    _syncStatusSubscription =
        eventBus.on<WalletSyncStatusChangedEvent>().listen(
      (event) {
        if (event.walletId != widget.wallet.walletId ||
            !_spinController.hasLoadedAnimation) {
          return;
        }
        switch (event.newStatus) {
          case WalletSyncStatus.unableToSync:
          case WalletSyncStatus.synced:
            if (!_refreshing) _spinController.stop?.call();
            break;
          case WalletSyncStatus.syncing:
            _spinController.repeat?.call();
            break;
        }
      },
    );

    super.initState();
  }

  @override
  void dispose() {
    _syncStatusSubscription.cancel();

    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final isDesktop = Util.isDesktop;

    return SizedBox(
      height: isDesktop ? 22 : 36,
      width: isDesktop ? 22 : 36,
      child: Semantics(
        label: "Refresh Button. Refreshes The Values In Summary.",
        excludeSemantics: true,
        child: MaterialButton(
          color: isDesktop
              ? Theme.of(context).extension<StackColors>()!.buttonBackSecondary
              : null,
          splashColor: Theme.of(context).extension<StackColors>()!.highlight,
          onPressed: () async {
            final wallet = widget.wallet;
            if (_refreshing || wallet.refreshMutex.isLocked) return;

            _refreshing = true;
            try {
              if (_spinController.hasLoadedAnimation) {
                _spinController.repeat?.call();
              }
              await wallet.refresh();
            } finally {
              _refreshing = false;
              if (mounted) _spinController.stop?.call();
            }
          },
          elevation: 0,
          highlightElevation: 0,
          hoverElevation: 0,
          padding: EdgeInsets.zero,
          materialTapTargetSize: MaterialTapTargetSize.shrinkWrap,
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(
              Constants.size.circularBorderRadius,
            ),
          ),
          child: RotatingArrows(
            spinByDefault: widget.initialSyncStatus == WalletSyncStatus.syncing,
            width: isDesktop ? 12 : 24,
            height: isDesktop ? 12 : 24,
            controller: _spinController,
            color: widget.overrideIconColor != null
                ? widget.overrideIconColor!
                : isDesktop
                    ? Theme.of(context)
                        .extension<StackColors>()!
                        .textFieldDefaultSearchIconRight
                    : Theme.of(context)
                        .extension<StackColors>()!
                        .textFavoriteCard,
          ),
        ),
      ),
    );
  }
}
